<?php
return function (Router $r) {
    $r->get('/life-admin',fn()=>View::render(__DIR__.'/views/index.php',['title'=>'Personal essentials','expiries'=>Db::all('SELECT * FROM life_expiries ORDER BY status,expires_on,id'),'subscriptions'=>Db::all('SELECT * FROM life_subscriptions ORDER BY status,renews_on,id'),'payments'=>Db::all('SELECT * FROM life_loan_payments ORDER BY paid_on DESC,id DESC'),'loans'=>Db::all('SELECT l.*,COALESCE(SUM(p.amount),0) paid FROM life_loans l LEFT JOIN life_loan_payments p ON p.loan_id=l.id GROUP BY l.id ORDER BY (l.original_amount>COALESCE(SUM(p.amount),0)) DESC,l.due_on IS NULL,l.due_on,l.id') ]));
    $r->post('/life-admin/expiry',function () { $kind=text_input('kind',40); if (!in_array($kind,['Document','Insurance','Warranty','Vehicle','Other'],true)) throw new InvalidArgumentException('Choose an expiry type.'); Db::run('INSERT INTO life_expiries(title,kind,expires_on,remind_days,notes) VALUES (?,?,?,?,?)',[text_input('title'),$kind,valid_date(text_input('expires_on')),int_range($_POST['remind_days'] ?? '',0,365),text_input('notes',2000,false)]); return redirect('/life-admin','Expiry saved.'); });
    $r->post('/life-admin/expiry/{id}/done',function ($p) { Db::run("UPDATE life_expiries SET status='done' WHERE id=?",[record_id($p['id'])]); return redirect('/life-admin','Expiry marked done.'); });
    $r->post('/life-admin/expiry/{id}/renew',function ($p) { $date=valid_date(text_input('expires_on')); Db::run("UPDATE life_expiries SET expires_on=?,status='active' WHERE id=?",[$date,record_id($p['id'])]); return redirect('/life-admin','Expiry date updated.'); });
    $r->post('/life-admin/subscription',function () { $cadence=text_input('cadence',20); if (!in_array($cadence,['monthly','yearly'],true)) throw new InvalidArgumentException('Choose a billing cycle.'); Db::run('INSERT INTO life_subscriptions(name,amount,cadence,renews_on,notes) VALUES (?,?,?,?,?)',[text_input('name'),cents($_POST['amount'] ?? '')/100,$cadence,valid_date(text_input('renews_on')),text_input('notes',2000,false)]); return redirect('/life-admin#subscriptions','Subscription saved.'); });
    $r->post('/life-admin/subscription/{id}/cancel',function ($p) { Db::run("UPDATE life_subscriptions SET status='cancelled' WHERE id=?",[record_id($p['id'])]); return redirect('/life-admin#subscriptions','Subscription marked cancelled.'); });
    $r->post('/life-admin/subscription/{id}/renew',function ($p) { $date=valid_date(text_input('renews_on')); Db::run("UPDATE life_subscriptions SET renews_on=?,status='active' WHERE id=?",[$date,record_id($p['id'])]); return redirect('/life-admin#subscriptions','Next renewal updated. No payment was created.'); });
    $r->post('/life-admin/loan',function () { $direction=text_input('direction',20); if (!in_array($direction,['lent','borrowed'],true)) throw new InvalidArgumentException('Choose lent or borrowed.'); Db::run('INSERT INTO life_loans(person,direction,original_amount,due_on,notes,created_on) VALUES (?,?,?,?,?,?)',[text_input('person'),$direction,cents($_POST['amount'] ?? '')/100,optional_date($_POST['due_on'] ?? ''),text_input('notes',2000,false),date('Y-m-d')]); return redirect('/life-admin#loans','Lend or borrow entry saved.'); });
    $r->post('/life-admin/loan/{id}/payment',function ($p) { $id=record_id($p['id']); $amount=cents($_POST['amount'] ?? '')/100; $date=valid_date(text_input('paid_on')); Db::tx(function () use ($id,$amount,$date) { $row=Db::one('SELECT l.original_amount,COALESCE(SUM(p.amount),0) paid FROM life_loans l LEFT JOIN life_loan_payments p ON p.loan_id=l.id WHERE l.id=? GROUP BY l.id',[$id]); if (!$row || round(($row['original_amount']-$row['paid'])*100)<round($amount*100)) throw new InvalidArgumentException('Payment exceeds the remaining amount.'); Db::run('INSERT INTO life_loan_payments(loan_id,paid_on,amount) VALUES (?,?,?)',[$id,$date,$amount]); }); return redirect('/life-admin#loans','Payment recorded.'); });
    $r->post('/life-admin/loan/{id}/payment/{payment}/delete',function ($p) { Db::run('DELETE FROM life_loan_payments WHERE loan_id=? AND id=?',[record_id($p['id']),record_id($p['payment'])]); return redirect('/life-admin#loans','Payment removed. The remaining balance has been recalculated.'); });
};

